record.field:
if records:
    for partner in records:
        if partner.company_id:
            partner.action_fix_stock_locations()

    # Notificar al usuario
    message = f"Se han corregido las ubicaciones de stock de {len(records.filtered(lambda p: p.company_id))} contactos."
    return {
        'type': 'ir.actions.client',
        'tag': 'display_notification',
        'params': {
            'title': 'Corrección Completada',
            'message': message,
            'type': 'success',
            'sticky': False,
        }
    }
